const mockBlockchainService = {
  isEnabled: vi.fn().mockReturnValue(true),
  anchorBatchRoot: vi.fn().mockResolvedValue('0xmocktxhash123'),
};

vi.mock('../blockchain', () => ({
  blockchainService: mockBlockchainService,
}));

// Import after mocks are set up
