describe('Edge Cases', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.useFakeTimers();
    mockBlockchainService.isEnabled.mockReturnValue(true);
    mockBlockchainService.anchorBatchRoot.mockResolvedValue('0xedge');
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('should handle events with special characters in payload', async () => {
    const service = new BatchAnchoringService({ enabled: true, maxBatchSize: 5 });
    
    const event = createTestEvent('special', {
      payload: {
        message: 'Test with "quotes" and \'apostrophes\'',
        unicode: '日本語テスト',
        emoji: '🔥💧⚡',
      },
    });
    
    service.queueEvent(event);
    const result = await service.forceBatch();
    
    expect(result).not.toBeNull();
    expect(result?.merkleRoot).toBeDefined();
    
    service.shutdown();
  });

  it('should handle events with very large payloads', async () => {
    const service = new BatchAnchoringService({ enabled: true, maxBatchSize: 5 });
    
    const largePayload = {
      data: 'x'.repeat(100000), // 100KB payload
      nested: {
        array: Array(1000).fill({ value: Math.random() }),
      },
    };
    
    const event = createTestEvent('large', { payload: largePayload });
    
    service.queueEvent(event);
    const result = await service.forceBatch();
    
    expect(result).not.toBeNull();
    expect(result?.eventCount).toBe(1);
    
    service.shutdown();
  });

  it('should handle timestamp edge cases', async () => {
    const service = new BatchAnchoringService({ enabled: true, maxBatchSize: 5 });
    
    const oldDate = new Date('2000-01-01T00:00:00Z');
    const futureDate = new Date('2100-01-01T00:00:00Z');
    
    service.queueEvent(createTestEvent('past', { timestamp: oldDate }));
    service.queueEvent(createTestEvent('future', { timestamp: futureDate }));
    
    const result = await service.forceBatch();
    
    expect(result?.eventCount).toBe(2);
    
    service.shutdown();
  });

  it('should handle rapid enable/disable cycles', async () => {
    const service = new BatchAnchoringService({ enabled: true, maxBatchSize: 10 });
    
    service.queueEvent(createTestEvent('1'));
    service.updateConfig({ enabled: false });
    
    const result1 = service.queueEvent(createTestEvent('2'));
    expect(result1.queued).toBe(false);
    
    service.updateConfig({ enabled: true });
    
    const result2 = service.queueEvent(createTestEvent('3'));
    expect(result2.queued).toBe(true);
    
    expect(service.getPendingEvents()).toHaveLength(2);
    
    service.shutdown();
  });

  it('should handle zero maxBatchAgeMs (immediate timer trigger)', async () => {
    const service = new BatchAnchoringService({
      enabled: true,
      maxBatchSize: 100,
      maxBatchAgeMs: 1, // Very short
    });
    
    service.queueEvent(createTestEvent('1'));
    
    await vi.advanceTimersByTimeAsync(5);
    
    expect(service.getStats().totalBatchesAnchored).toBe(1);
    
    service.shutdown();
  });
});
